CREATE EXTENSION IF NOT EXISTS "pgcrypto";

CREATE TABLE roles (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), name TEXT UNIQUE NOT NULL, description TEXT);
CREATE TABLE permissions (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), code TEXT UNIQUE NOT NULL, description TEXT);
CREATE TABLE role_permissions (role_id UUID REFERENCES roles(id) ON DELETE CASCADE, permission_id UUID REFERENCES permissions(id) ON DELETE CASCADE, PRIMARY KEY(role_id, permission_id));
CREATE TABLE farms (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), name TEXT NOT NULL, address TEXT, phone TEXT, created_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE users (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), farm_id UUID REFERENCES farms(id), role_id UUID NOT NULL REFERENCES roles(id), name TEXT NOT NULL, email TEXT UNIQUE NOT NULL, password_hash TEXT NOT NULL, email_verified_at TIMESTAMPTZ, is_active BOOLEAN NOT NULL DEFAULT true, created_at TIMESTAMPTZ NOT NULL DEFAULT now(), updated_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE sessions (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), user_id UUID NOT NULL REFERENCES users(id) ON DELETE CASCADE, token_hash TEXT NOT NULL, expires_at TIMESTAMPTZ NOT NULL, created_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE audit_logs (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), farm_id UUID REFERENCES farms(id), user_id UUID REFERENCES users(id), action TEXT NOT NULL, entity_type TEXT NOT NULL, entity_id UUID, metadata JSONB NOT NULL DEFAULT '{}', created_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE barns (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), farm_id UUID NOT NULL REFERENCES farms(id) ON DELETE CASCADE, name TEXT NOT NULL, capacity INTEGER, UNIQUE(farm_id, name));
CREATE TYPE cow_status AS ENUM ('active','sold','deceased','archived');
CREATE TYPE health_status AS ENUM ('healthy','sick','under_treatment');
CREATE TABLE cows (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), farm_id UUID NOT NULL REFERENCES farms(id) ON DELETE CASCADE, barn_id UUID REFERENCES barns(id), cow_code TEXT NOT NULL, ear_tag TEXT NOT NULL, name TEXT, breed TEXT, gender TEXT NOT NULL CHECK (gender IN ('female','male')), date_of_birth DATE, weight_kg NUMERIC(8,2), height_cm NUMERIC(8,2), color TEXT, purchase_date DATE, purchase_price NUMERIC(12,2), mother_id UUID REFERENCES cows(id), father_id UUID REFERENCES cows(id), status cow_status NOT NULL DEFAULT 'active', health health_status NOT NULL DEFAULT 'healthy', is_milking BOOLEAN NOT NULL DEFAULT false, is_pregnant BOOLEAN NOT NULL DEFAULT false, photo_url TEXT, created_at TIMESTAMPTZ NOT NULL DEFAULT now(), updated_at TIMESTAMPTZ NOT NULL DEFAULT now(), UNIQUE(farm_id, cow_code), UNIQUE(farm_id, ear_tag));
CREATE TABLE cow_images (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), cow_id UUID NOT NULL REFERENCES cows(id) ON DELETE CASCADE, url TEXT NOT NULL, is_primary BOOLEAN NOT NULL DEFAULT false, created_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE milk_records (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), farm_id UUID NOT NULL REFERENCES farms(id) ON DELETE CASCADE, cow_id UUID NOT NULL REFERENCES cows(id), worker_id UUID REFERENCES users(id), recorded_on DATE NOT NULL, morning_liters NUMERIC(7,2) NOT NULL DEFAULT 0 CHECK(morning_liters >= 0), afternoon_liters NUMERIC(7,2) NOT NULL DEFAULT 0 CHECK(afternoon_liters >= 0), evening_liters NUMERIC(7,2) NOT NULL DEFAULT 0 CHECK(evening_liters >= 0), fat_percent NUMERIC(4,2), snf_percent NUMERIC(4,2), temperature_c NUMERIC(4,1), collector TEXT, storage_tank TEXT, created_at TIMESTAMPTZ NOT NULL DEFAULT now(), UNIQUE(cow_id, recorded_on));
CREATE TABLE feed_types (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), farm_id UUID NOT NULL REFERENCES farms(id), name TEXT NOT NULL, unit TEXT NOT NULL, reorder_level NUMERIC(10,2) DEFAULT 0, UNIQUE(farm_id,name));
CREATE TABLE feed_inventory (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), feed_type_id UUID NOT NULL REFERENCES feed_types(id), quantity NUMERIC(10,2) NOT NULL DEFAULT 0, unit_cost NUMERIC(12,2), updated_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE feed_consumption (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), cow_id UUID REFERENCES cows(id), feed_type_id UUID NOT NULL REFERENCES feed_types(id), consumed_on DATE NOT NULL, quantity NUMERIC(10,2) NOT NULL, worker_id UUID REFERENCES users(id));
CREATE TABLE diseases (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), name TEXT UNIQUE NOT NULL, description TEXT);
CREATE TABLE medicines (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), farm_id UUID NOT NULL REFERENCES farms(id), name TEXT NOT NULL, stock_quantity NUMERIC(10,2) NOT NULL DEFAULT 0, expiry_date DATE);
CREATE TABLE treatments (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), cow_id UUID NOT NULL REFERENCES cows(id), disease_id UUID REFERENCES diseases(id), veterinarian_id UUID REFERENCES users(id), diagnosis TEXT, treatment_plan TEXT, diagnosed_on DATE NOT NULL DEFAULT CURRENT_DATE);
CREATE TABLE vaccinations (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), cow_id UUID NOT NULL REFERENCES cows(id), vaccine_name TEXT NOT NULL, due_on DATE NOT NULL, administered_on DATE, veterinarian_id UUID REFERENCES users(id));
CREATE TABLE breeding_records (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), cow_id UUID NOT NULL REFERENCES cows(id), method TEXT NOT NULL, serviced_on DATE NOT NULL, sire_reference TEXT, expected_calving_on DATE, result TEXT);
CREATE TABLE pregnancy_checks (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), breeding_record_id UUID NOT NULL REFERENCES breeding_records(id), checked_on DATE NOT NULL, is_pregnant BOOLEAN NOT NULL, veterinarian_id UUID REFERENCES users(id));
CREATE TABLE calves (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), farm_id UUID NOT NULL REFERENCES farms(id), mother_id UUID REFERENCES cows(id), father_id UUID REFERENCES cows(id), born_on DATE NOT NULL, birth_weight_kg NUMERIC(8,2), gender TEXT, status TEXT NOT NULL DEFAULT 'active');
CREATE TABLE employees (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), farm_id UUID NOT NULL REFERENCES farms(id), user_id UUID REFERENCES users(id), job_title TEXT, hired_on DATE, base_salary NUMERIC(12,2));
CREATE TABLE attendance (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), employee_id UUID NOT NULL REFERENCES employees(id), attended_on DATE NOT NULL, status TEXT NOT NULL, UNIQUE(employee_id, attended_on));
CREATE TABLE payroll (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), employee_id UUID NOT NULL REFERENCES employees(id), period_start DATE NOT NULL, period_end DATE NOT NULL, gross_amount NUMERIC(12,2) NOT NULL, paid_on DATE);
CREATE TABLE customers (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), farm_id UUID NOT NULL REFERENCES farms(id), name TEXT NOT NULL, phone TEXT, email TEXT);
CREATE TABLE suppliers (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), farm_id UUID NOT NULL REFERENCES farms(id), name TEXT NOT NULL, phone TEXT, email TEXT);
CREATE TABLE sales (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), farm_id UUID NOT NULL REFERENCES farms(id), customer_id UUID REFERENCES customers(id), sale_type TEXT NOT NULL, sale_date DATE NOT NULL, quantity NUMERIC(12,2), unit_price NUMERIC(12,2), total_amount NUMERIC(12,2) NOT NULL, payment_status TEXT NOT NULL DEFAULT 'pending');
CREATE TABLE expenses (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), farm_id UUID NOT NULL REFERENCES farms(id), category TEXT NOT NULL, amount NUMERIC(12,2) NOT NULL, incurred_on DATE NOT NULL, notes TEXT);
CREATE TABLE income (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), farm_id UUID NOT NULL REFERENCES farms(id), category TEXT NOT NULL, amount NUMERIC(12,2) NOT NULL, received_on DATE NOT NULL, notes TEXT);
CREATE TABLE inventory (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), farm_id UUID NOT NULL REFERENCES farms(id), item_name TEXT NOT NULL, category TEXT NOT NULL, quantity NUMERIC(10,2) NOT NULL DEFAULT 0, reorder_level NUMERIC(10,2) DEFAULT 0, expiry_date DATE);
CREATE TABLE notifications (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), farm_id UUID NOT NULL REFERENCES farms(id), user_id UUID REFERENCES users(id), type TEXT NOT NULL, title TEXT NOT NULL, body TEXT, read_at TIMESTAMPTZ, created_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE INDEX cows_farm_status_idx ON cows(farm_id, status); CREATE INDEX milk_records_farm_date_idx ON milk_records(farm_id, recorded_on); CREATE INDEX audit_logs_farm_created_idx ON audit_logs(farm_id, created_at DESC);
